const AaFont* aa_font(uint8_t scale, bool opt_in) {
    // Opt-in sizes (2) only when asked for.
    if (!opt_in && (scale == 2)) return nullptr;
    for (const AaFont& f : kFonts) {
        if (f.scale == scale) return &f;
    }
    return nullptr;
}

